// LoadPoolFundingRule loads the purchasePaymentFundingSnapshot's PoolFundingRule into the .R struct
func (o *PurchasePaymentFundingSnapshot) LoadPoolFundingRule(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.PoolFundingRule = nil
	o.R.Loaded.PoolFundingRule = false

	related, err := o.PoolFundingRule(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.PurchasePaymentFundingSnapshots = PurchasePaymentFundingSnapshotSlice{o}

	o.R.PoolFundingRule = related
	o.R.Loaded.PoolFundingRule = true
	return nil
}

// LoadPoolFundingRule loads the purchasePaymentFundingSnapshot's PoolFundingRule into the .R struct
func (os PurchasePaymentFundingSnapshotSlice) LoadPoolFundingRule(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	poolFundingRules, err := os.PoolFundingRule(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.PoolFundingRule = nil
		o.R.Loaded.PoolFundingRule = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range poolFundingRules {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.PoolID == rel.PoolID) {
				continue
			}

			if !(o.FundingRuleVersion == rel.Version) {
				continue
			}

			rel.R.PurchasePaymentFundingSnapshots = append(rel.R.PurchasePaymentFundingSnapshots, o)

			o.R.PoolFundingRule = rel
			break
		}
	}

	return nil
}

